def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(3 * w)] for _ in range(3 * h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0:
                for dr in range(h):
                    for dc in range(w):
                        if grid[dr][dc] == 0:
                            out[h * r + dr][w * c + dc] = value
    return out
